import os
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    if getattr(field, "value", None) is not None:
        return field.value
    return getattr(field, "content", None)


def _get_field(fields: Dict[str, Any], *names: str) -> Any:
    for name in names:
        if name in fields:
            return fields[name]
    return None


def extract_receipt(document_path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-receipt",
            body=f,
        )

    result = poller.result()

    merchant: Optional[str] = None
    tax: Optional[float] = None
    total: Optional[float] = None
    items: List[Dict[str, Any]] = []

    if result.documents:
        doc = result.documents[0]
        fields = doc.fields or {}

        merchant_field = _get_field(fields, "MerchantName")
        tax_field = _get_field(fields, "TotalTax")
        total_field = _get_field(fields, "Total")
        items_field = _get_field(fields, "Items")

        merchant = _field_value(merchant_field)

        tax_value = _field_value(tax_field)
        if hasattr(tax_value, "amount"):
            tax = _to_float(tax_value.amount)
        else:
            tax = _to_float(tax_value)

        total_value = _field_value(total_field)
        if hasattr(total_value, "amount"):
            total = _to_float(total_value.amount)
        else:
            total = _to_float(total_value)

        if items_field and getattr(items_field, "value", None):
            for item in items_field.value:
                item_fields = getattr(item, "value", {}) or {}
                description = _field_value(_get_field(item_fields, "Description", "Name"))
                quantity = _to_float(_field_value(_get_field(item_fields, "Quantity")))
                price_value = _field_value(_get_field(item_fields, "Price", "TotalPrice"))
                if hasattr(price_value, "amount"):
                    price = _to_float(price_value.amount)
                else:
                    price = _to_float(price_value)

                items.append(
                    {
                        "description": description,
                        "quantity": quantity,
                        "price": price,
                    }
                )

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
